) = VehicleDef(
    id = id, brand = brand, model = model, category = category, era = era, modelYear = modelYear,
    horsepower = horsepower, maxTorqueNm = maxTorqueNm, maxSpeedKmh = maxSpeedKmh,
    fuelCapacityL = fuelCapacityL, weightKg = weightKg, priceBrl = priceBrl,
    supportedHitches = supportedHitches, primaryColorRgb = primary, accentColorRgb = accent,
    bodyStyle = bodyStyle, wheelLayout = wheelLayout, hasCab = hasCab, dimensionsM = dims,
    turnRateDegPerSec = turnRate, soundProfile = soundProfile, hasGrainTank = hasGrainTank,
    tankCapacityL = tankCapacityL, gpsReady = gpsReady, description = description,
    requiredModPackId = requiredModPackId, subTypeLabel = subTypeLabel, series = series,
    tractorClass = tractorClass, exhaustStyle = exhaustStyle, hoodProfile = hoodProfile,
    visualSilhouette = visualSilhouette, headerWidthFt = headerWidthFt,
